pm.test("Reference car retrieved - 200", function () {
    pm.response.to.have.status(200);
});

if (pm.response.code === 200) {
    const cars = pm.response.json().content;

    pm.test("Reference car has model and categories", function () {
        pm.expect(cars).to.be.an("array").that.is.not.empty;
        pm.expect(cars[0].modelId).to.be.a("number");
        pm.expect(cars[0].categoryIds)
            .to.be.an("array").that.is.not.empty;
    });

    if (cars.length > 0 && cars[0].categoryIds.length > 0) {
        const car = cars[0];

        pm.collectionVariables.set("carModelId", car.modelId);
        pm.collectionVariables.set(
            "carCategoryIds",
            JSON.stringify(car.categoryIds)
        );
    } else {
        pm.execution.setNextRequest(null);
    }
} else {
    pm.execution.setNextRequest(null);
}

pm.test("Model cars retrieved - 200", function () {
    pm.response.to.have.status(200);
});

if (pm.response.code === 200) {
    const body = pm.response.json();

    pm.test("All model years fit into one page", function () {
        pm.expect(body.page.totalPages).to.eql(1);
    });

    if (body.page.totalPages !== 1) {
        pm.execution.setNextRequest(null);
    } else {
        const usedYears = new Set(
            body.content.map(car => Number(car.year))
        );

        let availableYear = new Date().getFullYear();

        while (availableYear >= 1900
                && usedYears.has(availableYear)) {
            availableYear--;
        }

        pm.test("Available manufacturing year found", function () {
            pm.expect(availableYear).to.be.at.least(1900);
        });

        if (availableYear >= 1900) {
            pm.collectionVariables.set(
                "carYear",
                availableYear
            );
        } else {
            pm.execution.setNextRequest(null);
        }
    }
} else {
    pm.execution.setNextRequest(null);
}

